#!/usr/bin/env python3
"""Generate independent Android design studies. No Flutter code or network I/O."""
import base64
import html
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent
ICONS = json.loads((ROOT / 'lucide-icons.json').read_text())


def icon(name, cls=''):
    svg = ICONS[name]
    svg = re.sub(r'width="24"', 'width="22"', svg)
    svg = re.sub(r'height="24"', 'height="22"', svg)
    return svg.replace('<svg', f'<svg aria-hidden="true" class="icon {cls}"', 1)


def ib(name, label, attrs=''):
    action = attrs or f'data-demo="{label}"'
    return f'<button class="ib" aria-label="{label}" {action}>{icon(name)}</button>'


def button(label, name=None, cls='primary', attrs=''):
    return f'<button class="btn {cls}" {attrs}>{icon(name) if name else ""}<span>{label}</span></button>'


def tag(text, cls=''):
    return f'<span class="tag {cls}">{text}</span>'


def header(title, subtitle='', back=True, action='more-horizontal'):
    return f'<header class="header">{ib("arrow-left", "Назад") if back else brand()}<div class="header-title"><b>{title}</b>{f"<small>{subtitle}</small>" if subtitle else ""}</div>{ib(action, "Поиск" if action == "search" else "Действия")}</header>'


def brand():
    return '<div class="brand" aria-label="Moru"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M4 25V7h5l7 10L23 7h5v18h-5V15l-7 9-7-9v10Z" fill="currentColor"/></svg></div>'


def nav(active):
    items = [('home', 'message-circle', 'Чаты'), ('files', 'folder', 'Работа'), ('apps', 'layout-grid', 'Приложения'), ('settings', 'settings-2', 'Настройки')]
    return '<nav class="nav" aria-label="Основная навигация">' + ''.join(f'<button class="nav-item {"selected" if k == active else ""}" data-go="{k}">{icon(i)}<span>{t}</span></button>' for k, i, t in items) + '</nav>'


def row(name, title, sub='', detail='', attrs='', cls=''):
    return f'<button class="row {cls}" {attrs}><span class="row-icon">{icon(name)}</span><span class="row-text"><b>{title}</b>{f"<small>{sub}</small>" if sub else ""}</span>{f"<span class=detail>{detail}</span>" if detail else ""}{icon("chevron-right", "chevron")}</button>'


def section(title, body, desc=''):
    return f'<section class="section"><div class="section-heading"><h2>{title}</h2>{f"<small>{desc}</small>" if desc else ""}</div>{body}</section>'


def toggle(title, desc='', on=True):
    return f'<button class="toggle-row" role="switch" aria-checked="{str(on).lower()}"><span><b>{title}</b>{f"<small>{desc}</small>" if desc else ""}</span><span class="switch"></span></button>'


def search(text):
    return f'<label class="search">{icon("search")}<input aria-label="{text}" placeholder="{text}"></label>'


def composer(agent=False, queued=False):
    selector = 'data-demo="Агент: Claude Code. Модель и подключение настраиваются в его профиле"' if agent else 'data-go="model"'
    return f'<div class="composer-wrap">{f"<button class=queue data-queue>{icon("clock")}<span>В очереди · 1 сообщение</span>{icon("chevron-right")}</button>" if queued else ""}<div class="composer"><textarea aria-label="Сообщение" placeholder="{ "Уточнить задачу…" if agent else "Спросите что угодно…"}" rows="1"></textarea><div class="composer-tools">{ib("plus", "Прикрепить файл")}<button class="model-chip" {selector}>{icon("bot" if agent else "sparkles")}<span>{"Claude Code" if agent else "GPT-5"}</span>{icon("chevron-down")}</button>{ib("mic", "Голосовой ввод")}{ib("square" if agent else "arrow-up", "Остановить" if agent else "Отправить")}</div></div></div>'


def chat_row(title, preview, time, name='message-circle', status=''):
    action = 'data-go="permission"' if status else 'data-go="agent"' if name == 'bot' else 'data-go="chat"' if title == 'Выходные в Казани' else f'data-demo="Чат: {title} — в пакете показан пример «Выходные в Казани»"'
    return f'<button class="chat-row" {action}><span class="chat-icon">{icon(name)}</span><span class="chat-row-text"><b>{title}</b><small>{preview}</small>{tag(status,"warning") if status else ""}</span><span class="time">{time}</span></button>'


def workspace_tabs(active):
    return '<div class="workspace-tabs">' + ''.join(f'<button class="{ "active" if active == k else ""}" data-go="{k}">{icon(i)}{t}</button>' for k,i,t in [('files','folder','Файлы'),('terminal','terminal','Терминал'),('browser','globe','Браузер')]) + '</div>'


