def onboard(key,title,step,symbol,lead,desc,content,cta='Продолжить',target=None):
    top=header('Добро пожаловать','Moru',step > 1,'more-horizontal')+'<div class="onboard-progress">'+''.join(f'<span class="{"filled" if n <= step else ""}"></span>' for n in range(1,5))+'</div>'
    body=f'<div class="pad"><span class="step-caption">ШАГ {step} ИЗ 4</span><div class="onboard-symbol">{icon(symbol)}</div><div class="title-block" style="padding-top:0"><h1>{lead}</h1><p>{desc}</p></div>{content}</div>'
    footer='<div class="onboard-footer">'+button(cta,'arrow-up-right','primary full',f'data-go="{target or "home"}"')+button('Пропустить',None,'text full',f'data-go="{target or "home"}"')+'</div>'
    add(key,title,body,footer,top)


