add('apps','Мини-приложения','<div class="pad"><div class="title-block" style="padding-top:4px"><h1>Ваши<br>мини-приложения</h1><p>Небольшие инструменты, которые агент сделал для вас.</p></div>'+search('Найти приложение')+'<div class="app-grid">'+''.join('<div class="app-card">'+ib('more-horizontal','Действия приложения '+t)+'<button class="app-icon" style="min-width:48px;min-height:48px" data-demo="Открыть '+t+'">'+icon(i)+'</button><h3>'+t+'</h3><p>'+d+'</p>'+tag(s,c)+'</div>' for i,t,d,s,c in [('database','Мой бюджет','Расходы, категории и итог месяца','2 фоновые задачи','accent'),('calendar-clock','План недели','Дела и свободное время в одном месте','Локально',''),('volume-2','Таймер фокуса','25 минут работы, 5 минут отдыха','Локально',''),('file-text','Список покупок','Соберите всё нужное перед выходом','1 ошибка','danger')])+'</div><div class="card tint" style="margin-top:18px"><h3>Есть идея для своего инструмента?</h3><p class="note" style="margin:7px 0">Опишите её агенту в чате.</p>'+button('Создать с агентом','plus','text full','data-go="agent"')+'</div><p class="note">Меню приложения: версии, задачи, сервер, ошибки, ярлык, поделиться и удалить.</p></div>',nav('apps'),header('Приложения','Созданы для вас',False,'more-horizontal'))

add('notification','Android: агент ждёт разрешения','<div class="system-header"><div class="system-time">14:32</div><div class="system-date">Четверг, 1 октября</div></div><div class="quick-settings"><div class="quick-tile active">'+icon('wifi')+'Домашняя сеть</div><div class="quick-tile">'+icon('bell')+'Со звуком</div></div><div class="brightness">'+icon('sun')+'</div><div class="notification-card"><div class="notification-top">'+brand()+'<span>Moru · сейчас</span>'+icon('chevron-down')+'</div><div class="inline" style="color:var(--warning);margin-bottom:12px">'+icon('shield-alert')+tag('Ожидает вашего решения','warning')+'</div><h2>Агент ждёт разрешения</h2><p><b>Сайт для кофейни</b><br>Claude Code хочет запустить команду.</p><pre>npm install</pre><small>Рабочая область: coffeeshop<br>Разрешение только для этой команды.</small><div class="notification-actions">'+button('Разрешить',None,'primary','data-demo="Однократное разрешение: проверка актуального запроса и разблокировки"')+button('Отклонить',None,'secondary','data-demo="Запрос отклонён"')+'</div>'+button('Открыть запрос','arrow-up-right','text full','data-go="permission"')+'</div><p class="notification-hint">Настройки конфиденциальности могут скрыть текст команды на экране блокировки.</p><div class="notification-card" style="padding:16px;margin-top:18px"><div class="inline">'+icon('terminal')+'<div><b style="font-size:13px">Moru работает в фоне</b><small>1 активная задача · можно остановить</small></div></div></div>',top='',cls='notification-phone')

JS = r'''
const phone=document.querySelector('.phone');const initialTheme=document.body.classList.contains('dark')?'dark':'light';
function toast(t){let e=document.querySelector('.toast');if(e)e.remove();e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=t;phone.append(e);setTimeout(()=>e.remove(),3200)}
function luminance(hex){let a=hex.match(/\w\w/g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:Math.pow((x+.055)/1.055,2.4));return .2126*a[0]+.7152*a[1]+.0722*a[2]}
let accentSeed=null;let lastBrightness=initialTheme;const checkSvg=__CHECK__,circleSvg=__CIRCLE__;
function accent(hex){accentSeed=hex;const dark=document.body.classList.contains('dark');const mix=(a,b,t)=>'#'+a.match(/\w\w/g).map((x,i)=>Math.round(parseInt(x,16)*(1-t)+parseInt(b.match(/\w\w/g)[i],16)*t).toString(16).padStart(2,'0')).join('');let resolved=hex;const bg=dark?'#1B1E26':'#FFFFFF';for(let i=0;i<40;i++){const a=luminance(resolved),b=luminance(bg);if((Math.max(a,b)+.05)/(Math.min(a,b)+.05)>=(dark?7:5.2))break;resolved=mix(resolved,dark?'#FFFFFF':'#000000',.08)}const light=luminance(resolved),white=1.05/(light+.05),ink=(light+.05)/.055;document.body.style.setProperty('--accent',resolved);document.body.style.setProperty('--on-accent',white>=ink?'#FFFFFF':'#111111');document.body.style.setProperty('--tint',mix(bg,resolved,dark?.18:.08));}
function theme(t,system=false){if(t==='light'||t==='dark'||t==='amoled')lastBrightness=t==='light'?'light':'dark';document.body.classList.remove('dark','amoled','glass');document.body.style.removeProperty('--accent');document.body.style.removeProperty('--on-accent');document.body.style.removeProperty('--tint');if(lastBrightness==='dark')document.body.classList.add('dark');if(t==='amoled')document.body.classList.add('amoled');if(t==='glass')document.body.classList.add('glass');document.querySelectorAll('[data-theme]').forEach(x=>x.classList.toggle('active',x.dataset.theme===t));document.querySelector('#system-theme')?.classList.toggle('active',system);if(accentSeed)accent(accentSeed);}
document.querySelectorAll('[data-theme]').forEach(x=>{x.classList.toggle('active',x.dataset.theme===initialTheme);x.addEventListener('click',()=>theme(x.dataset.theme))});
document.querySelectorAll('[data-demo]').forEach(x=>x.addEventListener('click',()=>toast(x.dataset.demo)));
document.querySelectorAll('[data-go]').forEach(x=>x.addEventListener('click',()=>{let key=x.dataset.go;const valid=KEYS;if(valid.includes(key)){let mode=document.body.classList.contains('dark')?'dark':'light';location.href=key+'-'+mode+'.html'}else toast('Раздел «'+x.textContent.trim()+'» описан в карте настроек README')}));
const sample=document.querySelector('#live-preview .sample-text');const formattedSample=sample?.innerHTML;
document.querySelectorAll('[role=switch]').forEach(x=>x.addEventListener('click',()=>{const on=x.getAttribute('aria-checked')!=='true';x.setAttribute('aria-checked',String(on));if(x.textContent.includes('Контрастный'))document.body.classList.toggle('code-contrast',on);if(x.textContent.includes('Markdown')){document.body.classList.toggle('markdown-source',on);if(sample){if(on)sample.textContent='Вот так. **Важное читается сразу.**\nКод тоже: `print("Привет")`';else sample.innerHTML=formattedSample}}}));
document.querySelectorAll('[data-choice]').forEach(group=>group.querySelectorAll('button').forEach(x=>x.addEventListener('click',()=>{group.querySelectorAll('button').forEach(b=>b.classList.remove('active'));x.classList.add('active');if(x.dataset.style){document.body.classList.toggle('app-bubble',x.dataset.style==='bubble');document.body.classList.toggle('plain-message',x.dataset.style==='plain')}if(group.dataset.choice==='onboard-theme'){theme(x.textContent==='Тёмная'?'dark':x.textContent==='Светлая'?'light':initialTheme,x.textContent==='Система')}if(group.dataset.choice==='reasoning'){const label=document.querySelector('.reasoning .tag');if(label)label.textContent=x.textContent}})));
document.querySelectorAll('[data-accent]').forEach(x=>x.addEventListener('click',()=>{document.querySelectorAll('[data-accent]').forEach(b=>b.classList.remove('active'));x.classList.add('active');accent(x.dataset.accent)}));
document.querySelector('.color-picker')?.addEventListener('input',e=>{document.querySelectorAll('[data-accent]').forEach(b=>b.classList.remove('active'));accent(e.target.value)});
document.querySelector('#font-choice')?.addEventListener('change',e=>document.body.style.setProperty('--font',e.target.value==='system'?'Arial,sans-serif':e.target.value==='serif'?'Georgia,serif':'Manrope,Arial,sans-serif'));
document.querySelector('[type=range]')?.addEventListener('input',e=>{document.body.style.setProperty('--message-size',e.target.value+'px');document.querySelector('#size-value').textContent=e.target.value+' sp'});
document.querySelector('#system-theme')?.addEventListener('click',()=>theme(initialTheme,true));document.querySelector('#wallpaper-control')?.addEventListener('click',()=>document.querySelector('#live-preview').classList.toggle('wallpaper-preview'));
document.querySelectorAll('[data-model]').forEach(x=>x.addEventListener('click',()=>{document.querySelectorAll('[data-model]').forEach(b=>{b.classList.toggle('selected',b===x);b.setAttribute('aria-pressed',String(b===x));const i=b.querySelector(':scope > .icon');if(i)i.outerHTML=b===x?checkSvg:circleSvg});toast('Выбрана модель '+x.dataset.model)}));
document.querySelectorAll('.language-row').forEach(x=>x.addEventListener('click',()=>{document.querySelectorAll('.language-row').forEach(b=>{b.classList.toggle('active',b===x);b.setAttribute('aria-pressed',String(b===x));const i=b.querySelector(':scope > .icon');if(i)i.outerHTML=b===x?checkSvg:circleSvg})}));
document.querySelectorAll('[data-auth]').forEach(x=>x.addEventListener('click',()=>{document.querySelectorAll('[data-auth]').forEach(b=>{b.classList.toggle('selected',b===x);b.setAttribute('aria-pressed',String(b===x));const i=b.querySelector('.between > .icon:last-child');if(i)i.outerHTML=b===x?checkSvg:circleSvg});toast(x.dataset.auth==='api'?'Дальше: сервис, ключ API, проверка и выбор модели':'Дальше: выбор сервиса, вход и доступные модели')}));
document.querySelectorAll('.search input').forEach(x=>x.addEventListener('input',()=>{const q=x.value.toLowerCase();document.querySelectorAll('.chat-row,.model-row,.app-card,.row').forEach(e=>e.classList.toggle('hidden',!e.textContent.toLowerCase().includes(q)))}));
document.querySelectorAll('.chips button').forEach(x=>x.addEventListener('click',()=>{x.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('active'));x.classList.add('active')}));
function sheet(title,content){document.querySelector('.modal-backdrop')?.remove();const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML='<section class="demo-sheet" role="dialog" aria-modal="true" aria-label="'+title+'"><h2>'+title+'</h2>'+content+'<button class="btn secondary" data-close>Закрыть</button></section>';phone.append(modal);modal.querySelector('[data-close]').onclick=()=>modal.remove();}
document.querySelector('[data-tool]')?.addEventListener('click',()=>sheet('Команда агента','<p class="note">Claude Code · coffeeshop · выполняется</p><div class="tool-body">npm run build<br>vite · сборка проекта…</div><p class="note">Это действие ACP-агента. Отдельная пользовательская сессия терминала не содержит его историю автоматически.</p>'));
document.querySelector('[data-queue]')?.addEventListener('click',()=>sheet('Очередь · 1 сообщение','<p class="note">Отправится после текущего ответа</p><div class="card"><b>1. Добавь часы работы и контакты</b><p class="note">Можно изменить или убрать до отправки.</p></div><button class="btn outline" onclick="this.textContent=\'Черновик открыт для редактирования\'">Изменить</button><button class="btn danger" onclick="this.previousElementSibling.remove();this.previousElementSibling.remove();this.remove()">Убрать из очереди</button>'));
document.querySelector('[data-browser-close]')?.addEventListener('click',()=>{document.querySelector('.floating-browser')?.remove();toast('Плавающее окно закрыто')});
'''


def build():
    output=ROOT/'html';output.mkdir(exist_ok=True)
    font=base64.b64encode((ROOT/'Manrope.ttf').read_bytes()).decode()
    css=f"@font-face{{font-family:Manrope;font-style:normal;font-weight:200 800;font-display:block;src:url(data:font/ttf;base64,{font}) format('truetype')}}"+CSS
    keys=json.dumps([s['key'] for s in SCREENS])
    licenses=json.dumps({'Lucide':(ROOT/'LUCIDE-LICENSE.txt').read_text(),'Manrope':(ROOT/'MANROPE-LICENSE.txt').read_text()},ensure_ascii=False)
    status='<div class="statusbar"><span>14:32</span><div class="status-icons"><span class="signal"><i></i><i></i><i></i></span>'+icon('wifi')+icon('battery')+'</div></div>'
    manifest=[]
    for n,s in enumerate(SCREENS,1):
        for mode in ['light','dark']:
            filename=f"{s['key']}-{mode}.html"
            script=JS.replace('KEYS',keys).replace('__CHECK__',json.dumps(icon('check'))).replace('__CIRCLE__',json.dumps(icon('circle')))
            doc=f'<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=390,initial-scale=1"><title>Moru v2 · {html.escape(s["title"])} · {mode}</title><script type="application/json" id="asset-licenses">{licenses}</script><style>{css}</style></head><body class="{mode}"><main class="phone {s["cls"]}" aria-label="{html.escape(s["title"])}">{status}{s["top"]}<div class="scroll">{s["body"]}</div>{s["footer"]}<div class="gesture" aria-hidden="true"></div></main><script>{script}</script></body></html>'
            (output/filename).write_text(doc)
            manifest.append({'id':n,'key':s['key'],'title':s['title'],'theme':mode,'html':'html/'+filename,'png':f"png/{s['key']}-{mode}.png"})
    (ROOT/'screens.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
    cards=''.join(f'<article><h2>{s["id"]:02d}. {html.escape(s["title"])} <small>{"Светлая" if s["theme"]=="light" else "Тёмная"}</small></h2><a href="{s["html"]}"><img loading="lazy" src="{s["png"]}" width="390" height="844" alt="{html.escape(s["title"])} — {s["theme"]}"></a><p><a href="{s["html"]}">Открыть HTML</a> · <a href="{s["png"]}">PNG @2x</a></p></article>' for s in manifest)
    (ROOT/'index.html').write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Moru v2 — все макеты</title><style>body{margin:0;padding:24px;background:#ECEDEB;color:#20222B;font:14px Arial,sans-serif}h1{font-size:36px;margin:0 0 12px}header{margin-bottom:30px}header p{max-width:750px;line-height:1.6}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,390px));gap:32px;justify-content:center}article{width:100%;min-width:0}h2{font-size:15px;min-height:42px;line-height:1.5}small{color:#626570;font-size:12px;display:block}img{width:100%;height:auto;border-radius:16px;box-shadow:0 6px 24px #0002}a{color:#5142D9}article p{font-size:13px}@media(max-width:480px){body{padding:16px}h1{font-size:28px}main{display:block}article{margin-bottom:28px}}</style><header><h1>Moru. Место для мысли и дела.</h1><p>Одно направление, 20 сценариев, 40 макетов. Каждый телефон — 390 × 844; PNG — 780 × 1688. Откройте HTML для живого превью и переходов. Это дизайн-документация Android, не новая Web-версия Moru.</p><a href="README.md">Разбор кода и план</a> · <a href="board.png">Вся PNG-доска</a></header><main>'+cards+'</main></html>')
    gallery=ROOT/'index.html'
    gallery.write_text(gallery.read_text().replace('20 сценариев, 40 макетов',f'{len(SCREENS)} сценарий, {len(manifest)} макета'))
    print(f'Generated {len(manifest)} standalone screens (390×844)')


if __name__=='__main__':
    build()
